package http_test

import (
	"context"
	"strings"
	"testing"

	"github.com/Subject-Void-LLC/the-pleiades/internal/catalog/http"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/collection"
)

// TestRequest_Registered is a starter test, generated by
// pleiades forge new-collection: it proves "http.request" registered itself
// through this package's own init(), with the manifest fields given at
// generation time.
func TestRequest_Registered(t *testing.T) {
	d, ok := collection.Lookup("http.request")
	if !ok {
		t.Fatalf("collection.Lookup(%q) found nothing; did this package's init() run?", "http.request")
	}
	if d.Manifest.Status != collection.StatusDeclared {
		t.Errorf("Manifest.Status = %v, want %v", d.Manifest.Status, collection.StatusDeclared)
	}
	if d.Manifest.ExecutionContext.RequiresElevation != false {
		t.Errorf("Manifest.ExecutionContext.RequiresElevation = %v, want %v",
			d.Manifest.ExecutionContext.RequiresElevation, false)
	}
}

// TestRequest_NotImplemented is a starter, table-driven proof of
// the "declared is not implemented" guardrail: the stub must return an
// explicit error, never success. Replace this table as real parameter
// cases are added once Request is actually implemented.
func TestRequest_NotImplemented(t *testing.T) {
	tests := []struct {
		name   string
		params map[string]any
	}{
		{name: "no params", params: nil},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := http.Request(context.Background(), nil, nil, tt.params)
			if err == nil {
				t.Fatal("expected an explicit not-implemented error, got nil")
			}
			if !strings.Contains(err.Error(), "not implemented") {
				t.Errorf("error = %q, want it to mention \"not implemented\"", err.Error())
			}
		})
	}
}
